// ¡Aprende! — Fiches des mots du journal espagnol (hors cours), partie 3
Object.assign(CRS_FB.es, {
  "pelota (persona)": { reg: "es", alt: [["pelotillero", "Espagne"], ["lameculos", "vulgaire, universel"], ["chupamedias", "Argentine, Chili, Pérou"], ["lambiscón", "Mexique"]], err: [["peloto", "Invariable : un pelota, una pelota."]], tip: "Espagne. Ser un pelota = être un lèche-bottes. Hacer la pelota a alguien = cirer les pompes. Chaque pays a son mot : chupamedias, lambiscón, lambón (Colombie)." },
  "vergüenza": { reg: "gen", alt: [["pena", "Mexique, Colombie, Amérique centrale : me da pena = j'ai honte"], ["corte", "Espagne, familier : me da corte"], ["pudor"], ["bochorno", "= honte cuisante"]], err: [["verguenza", "Avec tréma : vergüenza (on prononce le u)."], ["vergonza", "Vergüenza."]], tip: "Tener vergüenza = être timide, gêné. Sinvergüenza = sans-gêne, crapule. Vergüenza ajena = la honte pour quelqu'un d'autre. Attention : au Mexique, pena = honte, pas peine." },
  "qué vergüenza": { reg: "gen", alt: [["qué pena", "Mexique, Colombie"], ["qué corte", "Espagne"], ["qué bochorno"], ["tierra, trágame", "= je voudrais disparaître"]], err: [["que vergüenza", "Exclamatif : qué, avec accent."], ["qué vergonza", "Vergüenza."]], tip: "¡Qué vergüenza! pour soi (la honte !) ou comme reproche (c'est honteux !)." },
  "me da vergüenza": { reg: "gen", alt: [["me da pena", "Mexique, Colombie"], ["me da corte", "Espagne, familier"], ["me da cosa", "= ça me gêne un peu"], ["me avergüenza", "plus soutenu"]], err: [["tengo vergüenza de", "Plus naturel : me da vergüenza + infinitif."], ["me hace vergüenza", "DAR : me da vergüenza."]], tip: "Structure dar + nom : me da miedo, pena, asco, rabia, igual. Me da vergüenza hablar en público." },
  "flipante": { reg: "es", alt: [["alucinante", "Espagne"], ["increíble", "universel"], ["brutal", "Espagne"], ["padrísimo", "Mexique"], ["bárbaro", "Argentine"]], err: [["flippante", "Un seul p."], ["flipado", "Flipado = halluciné, ou frimeur."]], tip: "Argot d'Espagne. Flipar = halluciner : estoy flipando, ¡flipas! Équivalents : Mexique chido, padre ; Argentine copado ; Colombie chévere, bacano." },
  "jefe": { reg: "gen", alt: [["patrón"], ["encargado", "= responsable"], ["superior"], ["mandamás", "familier : le grand chef"]], err: [["chefe", "Avec j."], ["gefe", "Jefe."]], tip: "El jefe de Estado. Mexique : mi jefe = mon père ; ¡jefe! pour interpeller un homme. Espagne : ¡jefe! au bar pour appeler le serveur. Chef cuisinier = chef, cocinero." },
  "jefa": { reg: "gen", alt: [["patrona"], ["encargada"], ["directora"]], err: [["jefe", "Le féminin jefa est courant et admis."]], tip: "Mexique : mi jefa = ma mère. Familier : la jefa = ma femme, celle qui commande à la maison." },
  "cansar": { reg: "gen", alt: [["agotar", "= épuiser"], ["fatigar", "soutenu"], ["aburrir", "= lasser"], ["hartar", "= saouler"]], err: [["canser", "Verbe en -ar."], ["cansir", "Cansar."]], tip: "Este trabajo cansa. Me cansa = ça me fatigue, ça me lasse. Estoy cansado = je suis fatigué." },
  "cansarse de": { reg: "gen", alt: [["hartarse de", "plus fort : en avoir ras-le-bol"], ["aburrirse de"], ["estar harto de"], ["estar hasta las narices de", "Espagne, familier"]], err: [["cansarse a", "Cansarse DE."], ["cansarse con", "DE."]], tip: "Me cansé de esperar = j'en ai eu marre d'attendre. No me canso de escucharla = je ne m'en lasse pas." },
  "cansancio": { reg: "gen", alt: [["agotamiento", "= épuisement"], ["fatiga", "soutenu, médical"], ["sueño", "= sommeil"]], err: [["cansacio", "Cansancio."], ["cansansio", "Avec c : cansancio."]], tip: "Estoy muerto de cansancio. El cansancio acumulado. Hasta el cansancio = jusqu'à plus soif." },
  "partirse": { reg: "es", alt: [["partirse de risa", "forme complète"], ["mearse de risa", "familier"], ["descojonarse", "Espagne, vulgaire"], ["morirse de risa", "universel"], ["cagarse de risa", "Argentine, vulgaire"]], err: [["partirse a risa", "Partirse DE risa."]], tip: "Espagne, familier. Me parto = je suis mort de rire. Me parto contigo. Sens propre : se casser en deux." },
  "ola": { reg: "gen", alt: [["oleaje", "= la houle"], ["oleada", "= vague de gens, de crimes"]], err: [["hola", "Hola = bonjour. Ola = vague."], ["onda", "Onda = onde (radio, physique)."]], tip: "Hacer la ola (au stade). La nueva ola. Una ola de frío. Surfear una ola." },
  "ola de calor": { reg: "gen", alt: [["canícula"], ["calorón", "familier"], ["bochorno", "= chaleur étouffante"]], err: [["hola de calor", "Ola, sans h."], ["onda de calor", "OLA de calor."]], tip: "Estamos en plena ola de calor. Contraire : ola de frío." },
  "arruga": { reg: "gen", alt: [["pliegue", "= pli"], ["doblez", "= pliure"], ["patas de gallo", "= pattes d'oie"]], err: [["aruga", "Deux r."], ["arrugua", "Arruga."]], tip: "Crema antiarrugas. La arruga es bella. Una camisa llena de arrugas." },
  "arrugar": { reg: "gen", alt: [["estrujar", "= froisser en serrant"], ["fruncir", "= froncer : fruncir el ceño"]], err: [["arugar", "Deux r."], ["arrugé", "Prétérit : arrugué."]], tip: "Arrugar un papel. Arrugar la frente = plisser le front." },
  "arrugarse": { reg: "gen", alt: [["acobardarse", "= se dégonfler"], ["rajarse", "familier : se défiler"], ["achicarse", "= se faire tout petit"], ["encogerse", "= rétrécir"]], err: [["arugarse", "Deux r."]], tip: "Esta camisa se arruga mucho. Au figuré : no te arrugues = ne te dégonfle pas." },
  "no solo": { reg: "gen", alt: [["no solamente"], ["no únicamente"]], err: [["no sólo", "L'accent n'est plus recommandé : no solo."], ["no solo… pero también", "No solo… SINO también."]], tip: "No solo… sino también. Avec verbe conjugué : no solo canta, sino que también baila." },
  "preguntar": { reg: "gen", alt: [["consultar"], ["interrogar"], ["cuestionar", "= remettre en question"]], err: [["pedir", "Pedir = demander quelque chose. Preguntar = poser une question."], ["demandar", "Demandar = poursuivre en justice."]], tip: "Preguntar por alguien = demander des nouvelles ou demander à voir quelqu'un. Hacer una pregunta. Preguntarse = se demander." },
  "lamentar": { reg: "gen", alt: [["sentir", "lo siento : le plus courant"], ["arrepentirse de", "= regretter ce qu'on a fait"], ["deplorar", "soutenu"]], err: [["regretar", "Calque."], ["lamentar de", "Lamentar + nom ou infinitif, sans de."]], tip: "Lamento molestarle. Lamentamos informarle (style officiel). Lamentarse = se plaindre. Regretter une action = arrepentirse." },
  "lo lamento": { reg: "gen", alt: [["lo siento", "le plus courant"], ["perdón"], ["disculpa"], ["mi más sentido pésame", "= condoléances"]], err: [["lo lamente", "Lamento (yo)."], ["le lamento", "LO lamento."]], tip: "Plus formel que lo siento. Lo lamento mucho. S'emploie aussi pour un deuil." },
  "lamentable": { reg: "gen", alt: [["penoso", "= pitoyable"], ["patético"], ["vergonzoso", "= honteux"], ["triste"]], err: [["lamentabel", "Lamentable."]], tip: "Un espectáculo lamentable. Es lamentable que + subjonctif. Lamentablemente = malheureusement." },
  "chica": { reg: "gen", alt: [["tía", "Espagne, familier"], ["chavala", "Espagne"], ["mina", "Argentine"], ["chava", "Mexique"], ["muchacha", "Amérique latine"]], err: [["chika", "Avec c."]], tip: "Chico, chica = garçon, fille. En apostrophe : ¡chica! = ma vieille. Espagne : tío, tía. Adjectif : chico = petit (surtout Amérique latine)." },
  "señora": { reg: "gen", alt: [["doña", "+ prénom : doña Carmen"], ["mujer"], ["dama", "soutenu"], ["seño", "familier ; maîtresse d'école"]], err: [["senora", "Avec ñ."], ["madama", "Calque."]], tip: "Abréviation : Sra. La señora García. Mi señora = ma femme. Una señora casa = une sacrée maison." },
  "pegar": { reg: "gen", alt: [["golpear", "= frapper"], ["adherir", "= coller, soutenu"], ["contagiar", "= transmettre une maladie"], ["combinar", "= aller ensemble"]], err: [["pegar alguien", "Frapper quelqu'un = pegar A alguien."], ["peguar", "Pegar."]], tip: "Pegar un sello. Pegar a alguien. Me pegó la gripe. No pega = ça ne va pas ensemble. Pegar un grito, un salto. Copiar y pegar = copier-coller. No pegar ojo = ne pas fermer l'œil." },
  "pegar fuerte": { reg: "gen", alt: [["arrasar", "= tout rafler"], ["triunfar"], ["petarlo", "Espagne, argot"], ["romperla", "Amérique latine"]], err: [["pegar fuerza", "Fuerte."]], tip: "Esta canción está pegando fuerte = cette chanson cartonne. El sol pega fuerte = le soleil tape." },
  "venir": { reg: "gen", alt: [["llegar", "= arriver"], ["acudir", "= se rendre à"], ["acercarse", "= passer"]], err: [["vení", "Prétérit irrégulier : vine. (Vení est un impératif du voseo argentin.)"], ["ir", "Attention : j'arrive = ya voy, pas ya vengo."]], tip: "Vengo, vine, vendré, viniendo. Venir = vers celui qui parle ; ir = vers ailleurs. Me viene bien = ça m'arrange. Venga (Espagne) = allez, OK." },
  "vienes": { reg: "gen", alt: [["venís", "vosotros (Espagne), et vos (Argentine)"], ["viene", "usted"]], err: [["venes", "Diphtongue : vienes."]], tip: "Présent de venir : vengo, vienes, viene, venimos, venís, vienen. ¿Vienes o no?" },
  "vengo": { reg: "gen", alt: [["voy", "pour dire j'arrive : ya voy"]], err: [["veno", "1re personne irrégulière : vengo."], ["viengo", "Vengo."]], tip: "Verbes en -go : vengo, tengo, pongo, salgo, hago, digo, traigo. Vengo de Francia. Ahora vengo = je reviens tout de suite." },
  "conocer": { reg: "gen", alt: [["ubicar", "Amérique latine : situer quelqu'un"], ["encontrarse con", "= rencontrer"]], err: [["saber", "Saber = savoir. Conocer = connaître une personne, un lieu."], ["conoser", "Avec c."]], tip: "Conozco a Juan (a devant une personne). Au prétérit, conocí = j'ai rencontré pour la première fois. Encantado de conocerte. Dar a conocer = faire connaître." },
  "despertar": { reg: "gen", alt: [["despertarse", "= se réveiller"], ["levantar", "= faire lever"], ["espabilar", "Espagne : secouer, réveiller"]], err: [["desperto", "Diphtongue : despierto."], ["revellar", "Calque."]], tip: "Despierto, despiertas, despertamos. Me despierto a las siete. Estar despierto = être réveillé ; ser despierto = être vif. El despertador = le réveil." },
  "hace nada": { reg: "gen", alt: [["hace un momento"], ["ahora mismo", "Espagne : à l'instant"], ["recién", "Amérique latine : recién llegó"], ["hace un ratito"]], err: [["hace nadie", "Nada."], ["a nada", "Hace nada."]], tip: "Lo vi hace nada. Amérique latine : recién. Espagne : acabo de verlo." },
  "hace poco": { reg: "gen", alt: [["recientemente", "soutenu"], ["últimamente", "= ces derniers temps"], ["el otro día", "= l'autre jour"], ["recién", "Amérique latine"]], err: [["hace poquo", "Poco."], ["hay poco", "HACE poco."]], tip: "Hace + durée = il y a. Hace poco que vivo aquí. Desde hace poco = depuis peu." },
  "sortear": { reg: "gen", alt: [["esquivar", "= esquiver"], ["eludir", "soutenu"], ["rifar", "= mettre en tombola"], ["regatear", "foot : dribbler"]], err: [["sortar", "Sortear."], ["sortir", "Sortir = salir."]], tip: "Deux sens : tirer au sort (sortear un premio) et contourner (sortear un obstáculo, sortear al portero)." },
  "sorteo": { reg: "gen", alt: [["rifa", "= tombola"], ["lotería"], ["concurso", "= jeu-concours"]], err: [["sorteó", "Avec accent c'est le verbe."], ["sortea", "Sorteo."]], tip: "El sorteo de la Champions. Por sorteo = par tirage au sort. Sur les réseaux : participa en el sorteo." },
  "sacarle X a alguien": { reg: "gen", alt: [["llevarle X a alguien", "le sacas / le llevas dos años"], ["tener ventaja sobre"], ["aventajar en", "soutenu"]], err: [["sacar X a alguien", "Avec le pronom indirect : LE saca."]], tip: "Le saco dos años = j'ai deux ans de plus que lui. Le saca una cabeza = il le dépasse d'une tête. Le sacan tres puntos = ils ont trois points d'avance." },
  "salir con": { reg: "gen", alt: [["estar con", "= être avec"], ["andar con", "Amérique latine"], ["quedar con", "Espagne : voir quelqu'un"], ["ser novios"]], err: [["salir a", "Salir CON alguien."], ["sortir con", "Salir."]], tip: "Está saliendo con una chica. Salir con amigos. Aussi : salir con una tontería = sortir une bêtise." },
  "película": { reg: "gen", alt: [["peli", "familier, universel"], ["filme", "soutenu"], ["cinta", "style journalistique"], ["largometraje", "= long-métrage"]], err: [["pelicula", "Avec accent : película."], ["film", "Peu courant : película."]], tip: "Ver una peli. Una película de miedo. De película = digne d'un film, génial. Montarse una película (Espagne) = se faire des films." },
  "salir": { reg: "gen", alt: [["irse", "= partir"], ["marcharse", "Espagne"], ["estrenarse", "= sortir, pour un film"], ["aparecer"]], err: [["salo", "1re personne irrégulière : salgo."], ["sortir", "Mot français."]], tip: "Salgo, saldré, sal (impératif). Salir bien / mal = bien ou mal se passer. Me salió caro = ça m'a coûté cher. No me sale = je n'y arrive pas. Sale a su padre = il tient de son père. Salir de fiesta." },
  "crítica": { reg: "gen", alt: [["reseña", "= critique d'un film, d'un livre"], ["opinión"], ["reproche"]], err: [["critica", "Sans accent c'est le verbe (il critique). Le nom : crítica."], ["critique", "Mot français."]], tip: "La crítica = la critique, et les critiques en tant que groupe. Un crítico = un critique (personne). Una crítica constructiva." },
  "buenísimo": { reg: "gen", alt: [["genial"], ["riquísimo", "pour la nourriture"], ["estupendo", "Espagne"], ["bonísimo", "forme savante, rare"]], err: [["buenisimo", "Avec accent : buenísimo."], ["muy buenísimo", "Déjà superlatif : pas de muy."]], tip: "Superlatif en -ísimo. Está buenísimo = c'est délicieux ; pour une personne = canon. ¡Buenísimo! (Argentine) = super !" },
  "todo el mundo": { reg: "gen", alt: [["todos"], ["la gente"], ["cada uno", "= chacun"], ["todo quisqui", "Espagne, familier"]], err: [["todo el mundo saben", "Verbe au singulier : todo el mundo sabe."], ["todo mundo", "Avec el (todo mundo s'entend au Mexique)."]], tip: "Todo el mundo lo sabe. Verbe toujours au singulier." },
  "mejor": { reg: "gen", alt: [["superior"], ["preferible"]], err: [["más mejor", "Jamais más mejor."], ["más bueno", "Comparatif irrégulier : mejor."]], tip: "Mejor que = mieux que. El mejor = le meilleur. A lo mejor = peut-être. Mejor dicho = ou plutôt. Mejor no = il vaut mieux pas. Pluriel : mejores." },
  "desde que": { reg: "gen", alt: [["a partir de que"], ["desde", "+ nom ou date"]], err: [["desde de que", "Desde que."], ["después que", "Después de que = après que."]], tip: "Desde que llegó, no para de hablar. Desde que te conozco. Desde hace = depuis + durée." },
  "entró": { reg: "gen", alt: [["ha entrado", "passé composé, usage d'Espagne pour le passé récent"], ["pasó", "= il est passé, entré"]], err: [["entro", "Sans accent = j'entre (présent). Entró = il est entré."], ["entrió", "Verbe en -ar : entró."]], tip: "Prétérit, 3e personne des verbes en -ar : -ó. Entrar EN (Espagne) ou entrar A (Amérique latine)." },
  "fracaso": { reg: "gen", alt: [["derrota", "= défaite"], ["fiasco"], ["batacazo", "Espagne, familier : gamelle"], ["chasco", "= déception"]], err: [["fracasso", "Un seul s."], ["jaque", "Jaque = échec au roi."]], tip: "Un fracaso total. El fracaso escolar. Verbe : fracasar. Les échecs (jeu) = el ajedrez." },
  "verdadero": { reg: "gen", alt: [["real"], ["auténtico"], ["cierto", "= vrai, certain"], ["genuino"]], err: [["verdadoso", "Verdadero."], ["verdad", "Verdad = le nom, la vérité."]], tip: "Un verdadero amigo. ¿Verdadero o falso? Es verdad = c'est vrai. De verdad = pour de vrai." },
  "otra vez": { reg: "gen", alt: [["de nuevo"], ["nuevamente", "soutenu"], ["una vez más"]], err: [["una otra vez", "Jamais d'article indéfini devant otro : otra vez."], ["otra ves", "Vez."]], tip: "¿Otra vez? = encore ? Otra vez será = ce sera pour une autre fois. Volver a + infinitif = refaire." },
  "balancearse": { reg: "gen", alt: [["mecerse", "= se bercer"], ["columpiarse", "= se balancer sur une balançoire"], ["oscilar"], ["hamacarse", "Argentine"]], err: [["balansearse", "Avec c."], ["balancerse", "Balancearse."]], tip: "El columpio = la balançoire. Una mecedora = un fauteuil à bascule. El barco se balancea." },
  "gracioso": { reg: "gen", alt: [["divertido", "= amusant"], ["chistoso", "Amérique latine"], ["cómico"], ["salado", "Espagne, Andalousie"]], err: [["gracieux", "Faux ami : gracieux = elegante, grácil."], ["gratuito", "Gratuit = gratis."]], tip: "Faux ami : gracioso = drôle. ¡Qué gracioso! Hacerse el gracioso = faire le malin. Me hace gracia = ça m'amuse. No tiene gracia = ce n'est pas drôle." },
  "recordar": { reg: "gen", alt: [["acordarse de", "= se souvenir de"], ["rememorar", "soutenu"], ["hacer memoria"]], err: [["recordarse de", "On dit recordar algo OU acordarse DE algo."], ["recordo", "Diphtongue : recuerdo."]], tip: "Recuerdo ese día = me acuerdo de ese día. Recuérdame que… = rappelle-moi que. Me recuerdas a tu padre = tu me rappelles ton père. Faux ami : enregistrer = grabar." },
  "hace como": { reg: "gen", alt: [["hace unos", "hace unos diez años"], ["hace más o menos"], ["hace aproximadamente", "soutenu"]], err: [["hace cómo", "Sans accent."], ["hace cerca", "Hace cerca DE."]], tip: "Como + quantité = environ, à l'oral : hace como dos horas, éramos como veinte." },
  "predecir": { reg: "gen", alt: [["pronosticar"], ["prever", "= prévoir"], ["adivinar", "= deviner"], ["vaticinar", "soutenu"]], err: [["predicir", "Predecir."], ["predecido", "Participe irrégulier : predicho."]], tip: "Se conjugue comme decir : predigo, predije, predicho. Una predicción. Predecible = prévisible." },
  "justo alrededor de": { reg: "gen", alt: [["justo sobre", "Espagne : justo sobre las ocho"], ["más o menos a"], ["a eso de", "a eso de las ocho = vers huit heures"]], err: [["justo al rededor de", "Alrededor, en un mot."], ["justa alrededor", "Justo, invariable ici."]], tip: "Justo = adverbe : juste. Justo ahora, justo aquí, justo a tiempo." },
  "alrededor de": { reg: "gen", alt: [["cerca de", "= près de"], ["aproximadamente"], ["en torno a", "soutenu"], ["unos", "unos veinte"]], err: [["al rededor de", "En un mot."], ["alrededor a", "Alrededor DE."]], tip: "Alrededor de la casa. Alrededor de cien personas. Alrededor de las cinco." },
  "parece que": { reg: "gen", alt: [["al parecer"], ["por lo visto"], ["se ve que", "familier"], ["da la impresión de que"]], err: [["parece que venga", "Affirmatif : indicatif (parece que viene). Subjonctif seulement après no parece que."], ["aparece que", "Parece."]], tip: "Parece que va a llover. Me parece que sí. No parece que venga. Parece mentira = c'est incroyable." },
  "bastar": { reg: "gen", alt: [["ser suficiente"], ["alcanzar", "surtout Amérique latine : no me alcanza"], ["llegar", "Espagne : no me llega"]], err: [["sufir", "Calque."], ["baster", "Verbe en -ar."]], tip: "Basta con + infinitif = il suffit de. Con eso basta. Me basta y me sobra = j'en ai largement assez." },
  "basta": { reg: "gen", alt: [["ya está bien", "Espagne"], ["ya", "¡ya!"], ["se acabó", "= c'est fini"], ["suficiente"]], err: [["vasta", "Vasta = vaste."], ["bastante", "Bastante = assez (quantité)."]], tip: "¡Basta ya! = ça suffit maintenant ! Basta de tonterías. Hasta decir basta = à n'en plus pouvoir." },
  "vuelta": { reg: "gen", alt: [["regreso", "= retour"], ["giro", "= rotation"], ["paseo", "= promenade"], ["cambio", "Espagne : la monnaie rendue"], ["vuelto", "Amérique latine : la monnaie rendue"]], err: [["buelta", "Avec v."], ["volta", "Diphtongue : vuelta."]], tip: "Ida y vuelta = aller-retour. Dar una vuelta = faire un tour. A la vuelta = au retour, ou au coin de la rue. La Vuelta = le Tour d'Espagne. Partido de vuelta = match retour. Darle vueltas = ressasser." },
  "dar la vuelta": { reg: "gen", alt: [["girar"], ["voltear", "Amérique latine : retourner"], ["rodear", "= contourner"], ["dar media vuelta", "= faire demi-tour"]], err: [["hacer la vuelta", "DAR la vuelta."], ["dar el vuelto", "El vuelto = la monnaie (Amérique latine)."]], tip: "Dar la vuelta al mundo. Dale la vuelta a la tortilla (propre et figuré : renverser la situation). Darse la vuelta = se retourner." },
  "de vuelta": { reg: "gen", alt: [["de regreso", "plus courant en Amérique latine"], ["otra vez", "Argentine : de vuelta = encore"]], err: [["de volta", "Vuelta."], ["de retorno", "De vuelta ou de regreso."]], tip: "Estoy de vuelta. De vuelta a casa. En Argentine, de vuelta = de nouveau. Estar de vuelta de todo = être blasé." },
  "volver": { reg: "gen", alt: [["regresar", "plus courant en Amérique latine"], ["retornar", "soutenu"], ["devolver", "attention : = rendre un objet"]], err: [["volvo", "Diphtongue : vuelvo."], ["volvido", "Participe irrégulier : vuelto."]], tip: "Vuelvo, volví, vuelto. Volver a + infinitif = refaire : volver a empezar. Volverse loco = devenir fou. Rendre un objet = devolver." },
  "vuelto": { reg: "gen", alt: [["regresado"], ["el vuelto", "Amérique latine : la monnaie rendue"]], err: [["volvido", "Participe irrégulier : vuelto."], ["buelto", "Avec v."]], tip: "He vuelto = je suis revenu. Mêmes participes : devuelto, envuelto, resuelto. Amérique latine : quédese con el vuelto = gardez la monnaie." },
  "descartar": { reg: "gen", alt: [["excluir"], ["rechazar", "= rejeter"], ["desechar", "= jeter, écarter"], ["eliminar"]], err: [["descarter", "Verbe en -ar."], ["ecartar", "Calque."]], tip: "No descarto nada = je n'exclus rien. Descartar una hipótesis. Vient des cartes : se défausser. Queda descartado = c'est exclu." },
  "descartado": { reg: "gen", alt: [["excluido"], ["eliminado"], ["rechazado"]], err: [["descartao", "Prononciation relâchée ; écrire descartado."]], tip: "Eso está descartado = c'est hors de question. Sport : un jugador descartado = un joueur écarté du groupe." },
  "descarte": { reg: "gen", alt: [["eliminación"], ["exclusión"], ["baja", "sport : un absent"]], err: [["descarta", "Descarte."], ["descarto", "Descarte."]], tip: "Por descarte = par élimination. Sport : los descartes del entrenador = les joueurs non retenus. Pêche : les rejets." },
  "todavía": { reg: "gen", alt: [["aún", "équivalent exact"]], err: [["todavia", "Avec accent : todavía."], ["toda vía", "En un mot."]], tip: "Todavía no = pas encore. Todavía estoy aquí. Ne pas confondre avec siempre (toujours = à chaque fois)." },
  "no consigo": { reg: "gen", alt: [["no logro", "plus soutenu"], ["no puedo", "= je ne peux pas"], ["no me sale", "= ça ne vient pas"], ["no hay manera", "= rien à faire"]], err: [["no consigo a", "Conseguir + infinitif directement."], ["no conseguo", "Consigo (e→i)."]], tip: "No consigo dormir. Conseguir : consigo, consigues, conseguí. Attention : consigo = aussi « avec soi » : lleva el móvil consigo." },
  "imaginar": { reg: "gen", alt: [["imaginarse", "très courant : me imagino"], ["figurarse", "Espagne : ¡figúrate!"], ["suponer"]], err: [["imaginer", "Verbe en -ar."], ["imajinar", "Avec g."]], tip: "Me imagino que sí = j'imagine que oui. ¡Imagínate! = tu imagines ! No te puedes imaginar." },
  "niña": { reg: "gen", alt: [["chica"], ["nena", "affectueux ; Argentine"], ["chiquilla", "Espagne"], ["cría", "Espagne, familier"], ["chamaca", "Mexique"]], err: [["nina", "Avec ñ."], ["ninia", "Niña."]], tip: "La niña de mis ojos = la prunelle de mes yeux. La niña del ojo = la pupille. De niña = quand j'étais petite. Dans les chansons : mi niña = ma chérie." },
  "dar": { reg: "gen", alt: [["entregar", "= remettre"], ["regalar", "= offrir"], ["pasar", "pásame la sal"], ["ofrecer"]], err: [["do", "1re personne irrégulière : doy."], ["dí", "Prétérit sans accent : di, dio."]], tip: "Doy, di, dio, daba, dé (subjonctif). Verbe à tout faire : dar miedo, pena, asco, igual, las gracias, un paseo, clase. Me da que = j'ai l'impression que. ¡Dale! (Amérique latine) = vas-y, OK." },
  "dando": { reg: "gen", alt: [["entregando"]], err: [["dante", "Gérondif : dando."], ["dendo", "Dando."]], tip: "Estar + gérondif : estoy dando clase. Dando un paseo. Dándole vueltas = en y réfléchissant sans cesse (accent quand on colle le pronom)." },
  "dar ganas de": { reg: "gen", alt: [["entrar ganas de", "me entran ganas de"], ["apetecer", "Espagne : me apetece"], ["provocar", "Colombie, Venezuela : me provoca"], ["antojarse", "Mexique : se me antoja"]], err: [["dar ganas a", "Ganas DE."], ["dar envia de", "Calque."]], tip: "Me dan ganas de llorar (pluriel : les ganas sont le sujet). Espagne : me apetece. Mexique : se me antoja. Colombie : me provoca." },
  "dar miedo": { reg: "gen", alt: [["asustar"], ["aterrorizar"], ["acojonar", "Espagne, vulgaire"], ["dar pavor", "plus fort"]], err: [["hacer miedo", "DAR miedo."], ["dar miedo de", "Me da miedo + infinitif, sans de."]], tip: "Me da miedo volar. Me dan miedo las arañas (pluriel). Tener miedo de / a. Da miedo = ça fait peur ; familier : de miedo = génial." },
  "dar pena": { reg: "gen", alt: [["dar lástima", "= faire pitié"], ["entristecer"], ["dar vergüenza", "sens du Mexique et de la Colombie"]], err: [["hacer pena", "DAR pena."], ["dar de la pena", "Dar pena."]], tip: "Me da pena verlo así = ça me fait de la peine. Attention : au Mexique, en Colombie et en Amérique centrale, me da pena = j'ai honte. ¡Qué pena! = quel dommage (ou la honte)." },
  "dar un paseo": { reg: "gen", alt: [["dar una vuelta"], ["pasear"], ["salir a caminar", "Amérique latine"], ["ir de paseo"]], err: [["hacer un paseo", "DAR un paseo."], ["tomar un paseo", "Calque de l'anglais."]], tip: "Vamos a dar un paseo por el parque. Mandar a paseo (Espagne) = envoyer promener. El paseo marítimo = le front de mer." },
  "echar": { reg: "gen", alt: [["tirar", "= jeter"], ["despedir", "= licencier"], ["expulsar"], ["poner", "= mettre, verser"], ["botar", "Amérique latine : virer, jeter"]], err: [["hechar", "Sans h : echar. (Hecho vient de hacer.)"], ["echer", "Verbe en -ar."]], tip: "Verbe à tout faire en Espagne. Echar sal, echar gasolina, echar una carta. Lo echaron del trabajo. Echar de menos = manquer (Amérique latine : extrañar). Echar un vistazo, una mano, la culpa. Echar a + infinitif = se mettre à." },
  "echar de casa": { reg: "gen", alt: [["botar de la casa", "Amérique latine"], ["correr de la casa", "Mexique"], ["poner de patitas en la calle", "= mettre à la rue"], ["desalojar", "= expulser légalement"]], err: [["hechar de casa", "Echar, sans h."], ["echar de la casa", "En Espagne, sans article : de casa."]], tip: "Sus padres lo echaron de casa. En Espagne, casa sans article = chez soi : en casa, a casa, de casa." },
  "echar una siesta": { reg: "es", alt: [["echarse una siesta", "forme pronominale, très courante"], ["dormir la siesta"], ["tomar una siesta", "Amérique latine"], ["echar una cabezadita", "= piquer un petit somme"]], err: [["hacer una siesta", "Echar ou dormir la siesta."], ["hechar una siesta", "Sans h."]], tip: "Voy a echarme una siesta. En Amérique latine : tomar ou dormir una siesta." },
  "echarse a llorar": { reg: "gen", alt: [["ponerse a llorar"], ["romper a llorar", "= éclater en sanglots"], ["largarse a llorar", "Argentine"], ["soltar el llanto", "Amérique latine"]], err: [["echarse de llorar", "Echarse A."], ["hecharse a llorar", "Sans h."]], tip: "Echarse a + infinitif, pour des débuts brusques : echarse a reír, a correr, a temblar." },
  "buitre": { reg: "gen", alt: [["carroñero", "= charognard"], ["aprovechado", "= profiteur"], ["zopilote", "Mexique : l'oiseau"], ["gallinazo", "Colombie, Pérou : l'oiseau"]], err: [["buitro", "Buitre."], ["vuitre", "Avec b."]], tip: "Los fondos buitre = les fonds vautours. Familier : un buitre = un profiteur, ou un dragueur lourd. Buitrear = taper, gratter." },
  "anciano": { reg: "gen", alt: [["persona mayor", "le terme poli courant"], ["viejo", "direct, peut blesser"], ["abuelo", "familier"], ["adulto mayor", "Amérique latine, officiel"]], err: [["ancien", "Faux ami : ancien = antiguo."], ["anciano edificio", "Uniquement pour les personnes. Un bâtiment : antiguo."]], tip: "Faux ami partiel : anciano = très âgé, pour les personnes seulement. Ancien = antiguo ; mon ancien patron = mi antiguo jefe, mi exjefe." },
  "anciana": { reg: "gen", alt: [["señora mayor"], ["viejita", "affectueux, Amérique latine"], ["abuela", "familier"]], err: [["ancianna", "Un seul n."]], tip: "Una anciana de noventa años. Residencia de ancianos = maison de retraite (Amérique latine : asilo, hogar de ancianos)." },
  "personas mayores": { reg: "gen", alt: [["los mayores"], ["la tercera edad", "= le troisième âge"], ["adultos mayores", "Amérique latine"], ["ancianos"]], err: [["personas viejas", "Peu délicat : personas mayores."], ["personas majores", "Mayores."]], tip: "Mayor = plus âgé, grand. Mi hermano mayor. Cuando seas mayor. Ser mayor de edad = être majeur." },
  "los que": { reg: "gen", alt: [["quienes", "pour des personnes"], ["aquellos que", "soutenu"]], err: [["los quien", "Los que ou quienes."], ["esos que", "Calque : los que."]], tip: "Los que quieran venir (subjonctif si indéterminé). El que, la que, los que, las que, lo que (neutre : ce que)." },
  "las que": { reg: "gen", alt: [["quienes"], ["aquellas que", "soutenu"]], err: [["las quien", "Las que."], ["esas que", "Calque."]], tip: "Las que llegaron tarde. Lo que = ce que : lo que quiero." },
  "asistir": { reg: "gen", alt: [["acudir a", "= se rendre à"], ["ir a"], ["presenciar", "= être témoin de"], ["ayudar", "= aider"], ["atender", "= s'occuper de"]], err: [["asistir un evento", "Avec A : asistir a un evento."], ["assistir", "Un seul s."]], tip: "Asistir a clase = aller en cours. Asistir a un herido = porter secours. Faux ami inverse : atender = s'occuper de, pas attendre (esperar)." },
  "asistir a": { reg: "gen", alt: [["acudir a"], ["ir a"], ["estar presente en"], ["presenciar"]], err: [["asistir en", "Asistir A."], ["atender a", "Atender = s'occuper de."]], tip: "Asistieron a la boda doscientas personas. No pudo asistir a la reunión." },
  "asistencia": { reg: "gen", alt: [["presencia"], ["ayuda"], ["público", "= l'assistance, les gens présents"], ["pase de gol", "= passe décisive"]], err: [["assistencia", "Un seul s."], ["asistancia", "Asistencia."]], tip: "Asistencia médica. Asistencia en carretera = dépannage. Sport : dar una asistencia. Lista de asistencia = feuille de présence." },
  "asistente": { reg: "gen", alt: [["ayudante", "= aide, assistant"], ["participante"], ["auxiliar"], ["concurrente", "= participant"]], err: [["asistante", "Asistente."], ["assistente", "Un seul s."]], tip: "Los asistentes al congreso. Asistente virtual. El árbitro asistente = le juge de touche. Asistente social (Espagne : trabajador social)." },
  "dañino": { reg: "gen", alt: [["perjudicial", "soutenu"], ["nocivo"], ["malo para"], ["tóxico"]], err: [["danino", "Avec ñ."], ["dañoso", "Peu courant : dañino."]], tip: "Dañino para la salud. Una persona dañina = une personne toxique." },
  "dañar": { reg: "gen", alt: [["estropear", "Espagne : abîmer"], ["perjudicar", "= nuire à"], ["averiar", "= mettre en panne"], ["malograr", "Pérou"], ["descomponer", "Mexique : mettre en panne"]], err: [["danar", "Avec ñ."], ["domajar", "Calque."]], tip: "El granizo dañó los coches. Dañarse = s'abîmer ; en Colombie et au Venezuela : tomber en panne (se dañó el carro)." },
  "daño": { reg: "gen", alt: [["perjuicio", "= préjudice"], ["lesión", "= blessure"], ["desperfecto", "= dégât matériel"], ["destrozo"]], err: [["dano", "Avec ñ."], ["damage", "Calque."]], tip: "Daños y perjuicios = dommages et intérêts. Daños colaterales. Hacerse daño = se faire mal." },
  "hacer daño": { reg: "gen", alt: [["lastimar", "surtout Amérique latine"], ["herir", "= blesser"], ["perjudicar"], ["doler", "me duele = j'ai mal"]], err: [["dar daño", "HACER daño."], ["hacer mal", "Se dit en Argentine ; ailleurs hacer daño."]], tip: "Me haces daño = tu me fais mal. Me hice daño en la rodilla. El alcohol hace daño. Sin hacer daño a nadie." },
  "maleta": { reg: "gen", alt: [["valija", "Argentine, Uruguay"], ["equipaje", "= les bagages"], ["petaca", "Mexique"], ["maletín", "= mallette"]], err: [["maletta", "Un seul t."], ["valisa", "Calque."]], tip: "Espagne, Mexique, Colombie : maleta. Río de la Plata : valija. Maleta de mano = bagage cabine. Mexique, familier : ser maleta = être nul." },
  "maletín": { reg: "gen", alt: [["cartera", "= porte-documents ; aussi portefeuille"], ["portafolios", "Amérique latine"], ["estuche", "= étui"]], err: [["maletin", "Avec accent : maletín."], ["maletino", "Maletín."]], tip: "Diminutif de maleta. Pluriel sans accent : maletines. El maletín del médico." },
  "hacer la maleta": { reg: "gen", alt: [["hacer las maletas", "pluriel, très courant"], ["empacar", "Amérique latine"], ["armar la valija", "Argentine"], ["hacer el equipaje"]], err: [["hacer su maleta", "Article défini : hacer LA maleta."], ["preparar la valisa", "Maleta."]], tip: "Tengo que hacer la maleta. Contraire : deshacer la maleta. Amérique latine : empacar, desempacar." },
  "capacidad": { reg: "gen", alt: [["habilidad", "= habileté"], ["aptitud"], ["aforo", "= capacité d'accueil d'une salle"], ["cabida", "= contenance"]], err: [["capasidad", "Avec c."], ["capacitad", "Capacidad."]], tip: "Capacidad para + infinitif. Aforo completo = complet. Estar al máximo de su capacidad." },
  "incapaz": { reg: "gen", alt: [["inepto", "péjoratif"], ["incompetente"], ["negado", "Espagne : nul pour quelque chose"]], err: [["incapas", "Avec z."], ["incapable", "Calque."]], tip: "Incapaz de + infinitif. Pluriel : incapaces. Soy incapaz de mentir." },
  "capacitar": { reg: "latam", alt: [["formar", "Espagne : former"], ["entrenar", "= entraîner"], ["habilitar", "= habiliter"], ["preparar"]], err: [["capasitar", "Avec c."], ["capacitar a hacer", "Capacitar PARA."]], tip: "Très courant en Amérique latine : una capacitación = une formation. En Espagne : formación, cursillo." },
  "ser capaz de": { reg: "gen", alt: [["poder"], ["lograr", "= parvenir à"], ["atreverse a", "= oser"], ["estar en condiciones de"]], err: [["estar capaz de", "Avec SER."], ["ser capaz a", "Capaz DE."]], tip: "No soy capaz de entenderlo. ¿Eres capaz? = t'es cap ? ¡Es capaz! = il en est bien capable. Amérique latine : capaz que = peut-être que." },
  "fallido": { reg: "gen", alt: [["frustrado", "= avorté"], ["fracasado"], ["malogrado"], ["errado"]], err: [["fallado", "Fallado = participe de fallar. L'adjectif : fallido."], ["falido", "Deux l."]], tip: "Un intento fallido. Un golpe de Estado fallido. Un acto fallido = un acte manqué. Un Estado fallido." },
  "fallar": { reg: "gen", alt: [["errar", "= manquer"], ["fracasar", "= échouer"], ["estropearse", "= tomber en panne"], ["defraudar", "= décevoir"]], err: [["faltar", "Faltar = manquer (être absent). Fallar = rater, échouer."], ["faillir", "Calque."]], tip: "Fallar un penalti. Me has fallado = tu m'as déçu. Los frenos fallaron. Sin fallar = sans faute. No falla = ça ne rate jamais. Juridique : rendre un verdict." },
  "fallo": { reg: "es", alt: [["error", "universel"], ["falla", "Amérique latine : défaut, panne, faille"], ["avería", "= panne"], ["sentencia", "= jugement"], ["defecto"]], err: [["falo", "Deux l."], ["fayo", "Avec ll."]], tip: "Espagne : un fallo = une erreur, une panne. Amérique latine : una falla. Partout : el fallo del juez = le verdict. Espagne : ¡qué fallo! = la boulette !" },
  "fallo técnico": { reg: "es", alt: [["falla técnica", "Amérique latine"], ["avería", "= panne"], ["problema técnico", "universel"], ["error del sistema"]], err: [["fallo tecnico", "Avec accent : técnico."], ["falta técnica", "Falta técnica = faute technique (basket)."]], tip: "Por un fallo técnico. En Amérique latine : por una falla técnica." },
  "conozco": { reg: "gen", alt: [["sé", "pour un fait ou un savoir-faire"], ["me suena", "= ça me dit quelque chose"]], err: [["conoco", "Avec zc : conozco."], ["conosco", "Conozco."]], tip: "Verbes en -cer ou -cir après voyelle : -zco à la 1re personne. Conozco, parezco, agradezco, conduzco, traduzco. Subjonctif : conozca." },
  "quitar": { reg: "gen", alt: [["sacar", "= enlever, sortir"], ["retirar"], ["eliminar"], ["robar", "me quitaron el móvil = on m'a piqué"]], err: [["quittar", "Un seul t."], ["quitar a alguien", "Quitter quelqu'un = dejar a alguien. Quitar ne veut jamais dire quitter."]], tip: "Faux ami majeur : quitar = enlever. Quitarse la ropa. Quita la mano. ¡Quita! (Espagne) = dégage. Me quitas un peso de encima. Quitando eso = à part ça." },
  "quitarse de en medio": { reg: "gen", alt: [["apartarse", "= s'écarter"], ["hacerse a un lado"], ["esfumarse", "= s'éclipser"], ["correrse", "Amérique latine ; vulgaire en Espagne"]], err: [["quitarse del medio", "Forme figée : de en medio."], ["quitarse en medio", "DE en medio."]], tip: "¡Quítate de en medio! = pousse-toi ! Quitar a alguien de en medio = se débarrasser de quelqu'un. Attention à correrse en Espagne." },
  "quitarse el sombrero": { reg: "gen", alt: [["hacer una reverencia"], ["chapó", "Espagne : ¡chapó! = chapeau !"], ["felicitar"], ["rendirse ante"]], err: [["tirar su sombrero", "Calque."], ["quitar el sombrero", "Pronominal : quitarSE."]], tip: "Me quito el sombrero = chapeau bas. Hay que quitarse el sombrero ante ella. Espagne : ¡chapó!" },
  "quitarse años": { reg: "gen", alt: [["hacerse el joven"], ["mentir sobre la edad"]], err: [["quitarse anos", "Avec ñ : años. Ano = anus."], ["quitar años", "Quitar años (sans se) = rajeunir quelqu'un."]], tip: "Siempre se quita años. Ese corte te quita años = cette coupe te rajeunit. Contraire : ponerse años, echar años." },
  "el estampado": { reg: "gen", alt: [["el dibujo", "= le motif"], ["el diseño"], ["el motivo"], ["la estampa"]], err: [["la estampada", "Masculin : el estampado."], ["el imprimado", "Calque."]], tip: "Un estampado de flores. Una camisa estampada. Contraire : liso = uni." },
  "estampar": { reg: "gen", alt: [["imprimir"], ["sellar", "= tamponner"], ["estrellar", "= écraser contre"], ["plantar", "familier : plantar un beso"]], err: [["estamper", "Verbe en -ar."], ["estampillar", "Estampillar = timbrer (Amérique latine)."]], tip: "Estampar la firma = apposer sa signature. Estampar una camiseta. Familier : estampó el móvil contra la pared." },
  "estamparse contra": { reg: "gen", alt: [["estrellarse contra"], ["chocar contra"], ["darse contra"], ["pegársela", "Espagne, familier"]], err: [["estamparse en", "CONTRA."], ["estamparse a", "CONTRA."]], tip: "Se estampó contra un árbol. Registre familier ; neutre : chocar contra." },
  "aclarar": { reg: "gen", alt: [["explicar"], ["esclarecer", "soutenu"], ["precisar"], ["enjuagar", "= rincer"], ["despejar", "= dissiper"]], err: [["clarificar", "Existe, mais aclarar est bien plus courant."], ["eclarar", "Aclarar."]], tip: "Quiero aclarar una cosa. Aclarar la ropa = rincer le linge (Espagne). Aclararse la garganta = s'éclaircir la voix. Aclararse el pelo." },
  "aclararse": { reg: "es", alt: [["despejarse", "pour le ciel"], ["entenderse"], ["organizarse"], ["decidirse"]], err: [["aclararse de", "Aclararse CON."], ["esclararse", "Aclararse."]], tip: "Espagne, familier : no me aclaro = je m'y perds. ¡A ver si te aclaras! = décide-toi ! Se aclaró el cielo." },
  "la aclaración": { reg: "gen", alt: [["la explicación"], ["la precisión"], ["la puntualización", "soutenu"], ["el matiz", "= la nuance"]], err: [["el aclaración", "Féminin."], ["la aclaracion", "Avec accent."]], tip: "Una aclaración : no dije eso. Pedir aclaraciones. Sin más aclaraciones." },
  "aclarar dudas": { reg: "gen", alt: [["resolver dudas"], ["despejar dudas", "= dissiper les doutes"], ["sacar de dudas", "sacar a alguien de dudas"], ["contestar preguntas"]], err: [["aclarar dudos", "Féminin : la duda, las dudas."], ["levantar dudas", "Calque."]], tip: "¿Alguna duda? = des questions ? Tengo una duda = j'ai une question. En espagnol, duda = souvent simple question." },
  "ponerse el tono de alguien": { reg: "gen", alt: [["imitar a alguien"], ["remedar", "= singer"], ["copiar el acento"], ["hablar como"]], err: [["ponerse al tono", "Ponerse a tono = se mettre au diapason : autre sens."]], tip: "Expression peu figée. Plus courant : imitar el tono, poner la voz de alguien. Ponerse a tono = se mettre dans l'ambiance." },
  "joya": { reg: "gen", alt: [["alhaja", "= bijou précieux"], ["tesoro"], ["bisutería", "= bijoux fantaisie"], ["maravilla"]], err: [["joia", "Avec y."], ["joyo", "Féminin."]], tip: "La joyería = la bijouterie. Es una joya = c'est une perle (personne ou objet). Ironique : ¡menuda joya! = quel numéro." },
  "¡joya!": { reg: "latam", alt: [["genial", "universel"], ["bárbaro", "Argentine"], ["buenísimo", "Argentine"], ["de lujo"], ["guay", "Espagne"]], err: [["joia", "Avec y."]], tip: "Argentine et Uruguay uniquement. ¿Todo bien? ¡Joya! Estuvo joya. En Espagne, on ne le dit pas : guay, genial." },
  "el vencimiento": { reg: "gen", alt: [["la caducidad", "Espagne : date de péremption"], ["el plazo", "= le délai"], ["la fecha límite"], ["la expiración"]], err: [["la vencimiento", "Masculin."], ["el vencimento", "Avec ie."]], tip: "Fecha de vencimiento. Espagne : fecha de caducidad pour les aliments, vencimiento pour les paiements. Verbe : vencer (el plazo vence mañana) ; Espagne : caducar." },
  "sumar": { reg: "gen", alt: [["añadir", "= ajouter"], ["agregar", "= ajouter, surtout Amérique latine"], ["acumular"], ["totalizar"]], err: [["adicionar", "Rare : sumar."], ["sommar", "Calque."]], tip: "Dos más dos suman cuatro. Sumar puntos. Suma y sigue = et ça continue. Contraire : restar. Una suma = une addition, une somme." },
  "sumarse a": { reg: "gen", alt: [["unirse a"], ["apuntarse a", "Espagne : s'inscrire, se joindre"], ["adherirse a"], ["incorporarse a"], ["prenderse", "Argentine : me prendo"]], err: [["sumarse con", "Sumarse A."], ["sumarse en", "A."]], tip: "Me sumo = j'en suis. Sumarse a una huelga, a una iniciativa. Espagne : me apunto. Argentine : me prendo. Mexique : le entro, me apunto." },
  "se parte de risa": { reg: "es", alt: [["se muere de risa", "universel"], ["se mea de risa", "familier"], ["se descojona", "Espagne, vulgaire"], ["se caga de risa", "Argentine, vulgaire"]], err: [["se parte a risa", "DE risa."], ["se parta de risa", "Indicatif : se parte."]], tip: "Espagne, familier. Me parto de risa contigo. Es para partirse = c'est à mourir de rire." },
  "meter a alguien": { reg: "gen", alt: [["poner a alguien"], ["colocar", "= placer, caser"], ["involucrar", "= impliquer"], ["enchufar", "Espagne : pistonner"]], err: [["meter alguien", "A devant une personne : meter A alguien."]], tip: "Lo metieron en la cárcel. Meter a alguien en un lío. No me metas en esto = ne me mêle pas à ça." },
  "haber roto": { reg: "gen", alt: [["haber quebrado", "Amérique latine : avoir cassé"], ["haber cortado", "= avoir rompu (couple)"], ["haber terminado"]], err: [["haber rompido", "Participe irrégulier : roto."], ["ser roto", "Auxiliaire HABER."]], tip: "Participes irréguliers : roto, hecho, dicho, visto, puesto, vuelto, escrito, abierto, muerto. He roto con ella = j'ai rompu avec elle." },
  "hasta tercero": { reg: "gen", alt: [["hasta tercer curso", "Espagne"], ["hasta tercer año", "Amérique latine"], ["hasta tercer grado", "Amérique latine, primaire"]], err: [["hasta tercer", "Seul : tercero. Devant un nom masculin : tercer."], ["hasta tresero", "Tercero."]], tip: "Tercero s'apocope devant un nom : tercer curso, mais estoy en tercero. Espagne : tercero de la ESO, tercero de carrera." },
  "atrasarse": { reg: "latam", alt: [["retrasarse", "Espagne, et universel"], ["demorarse", "Amérique latine"], ["llegar tarde"], ["tardar"]], err: [["atrazarse", "Avec s."], ["atrasarse de", "Atrasarse EN / CON."]], tip: "Amérique latine : atrasarse, demorarse. Espagne : retrasarse. El tren se atrasó. Me atrasé con el alquiler. El reloj atrasa." },
  "chocado": { reg: "gen", alt: [["estrellado"], ["accidentado"], ["impactado", "= choqué, au sens émotionnel"], ["sorprendido"]], err: [["chocao", "Prononciation relâchée ; écrire chocado."], ["choqué", "Choqué = prétérit de chocar (j'ai heurté)."]], tip: "Participe de chocar. Han chocado dos trenes. Me choca = ça me choque ; au Mexique, me choca = je déteste. ¡Chócala! = tope là !" },
  "hubo": { reg: "gen", alt: [["ha habido", "passé composé"], ["había", "imparfait : description"]], err: [["hubieron", "Impersonnel, toujours singulier : hubo muchos problemas."], ["ubo", "Avec h."]], tip: "Prétérit de hay. Hubo un accidente (événement ponctuel). Había mucha gente (décor). Erreur fréquente même chez les natifs : hubieron." },
  "descarrilamiento": { reg: "gen", alt: [["accidente ferroviario"], ["descarrilo", "Amérique latine, rare"]], err: [["descarilamiento", "Deux r."], ["desrailamiento", "Calque."]], tip: "Vient de carril (rail, voie). Verbe : descarrilar. Au figuré : el proyecto descarriló." },
  "hacer felices": { reg: "gen", alt: [["alegrar", "= réjouir"], ["dar felicidad"], ["contentar"], ["hacer dichosos", "soutenu"]], err: [["hacer felizes", "Z devient c au pluriel : felices."], ["rendir felices", "Calque : rendre heureux = hacer feliz."]], tip: "Rendre + adjectif = hacer, poner, volver. Me haces feliz. Me pone triste. Me vuelve loco." },
  "a punto de": { reg: "gen", alt: [["al borde de", "= au bord de"], ["por", "estoy por salir : Amérique latine"], ["casi"]], err: [["al punto de", "Al punto de = au point de (autre sens)."], ["a punta de", "A punta de = à force de (Amérique latine) ; a punta de pistola."]], tip: "Estar a punto de + infinitif. Estuve a punto de caerme = j'ai failli tomber. A punto (seul) = prêt, à point." },
  "estrellarse": { reg: "gen", alt: [["chocar"], ["estamparse", "familier"], ["accidentarse"], ["fracasar", "au figuré"], ["pegársela", "Espagne"]], err: [["estrelarse", "Deux l."], ["estrellarse a", "Estrellarse CONTRA."]], tip: "El avión se estrelló. Vient de estrella : voir des étoiles. Au figuré : se estrelló en los exámenes. Huevos estrellados." },
  "llanto": { reg: "gen", alt: [["lágrimas", "= larmes"], ["lloro"], ["sollozos", "= sanglots"], ["lloriqueo", "= pleurnicherie"]], err: [["yanto", "Avec ll."], ["llante", "Llanta = jante, pneu."]], tip: "Nom de llorar. Romper en llanto = fondre en larmes. El llanto de un bebé." },
  "aliviar": { reg: "gen", alt: [["calmar"], ["mitigar", "soutenu"], ["aligerar", "= alléger"], ["consolar"]], err: [["alivar", "Aliviar."], ["soulajar", "Calque."]], tip: "Aliviar el dolor. ¡Qué alivio! = quel soulagement ! Mexique : ¡que te alivies! = bon rétablissement ; aliviarse = aussi accoucher." },
  "indeseable": { reg: "gen", alt: [["indeseado", "= non désiré"], ["non grato", "persona non grata"], ["sinvergüenza", "= crapule"], ["impresentable", "Espagne"]], err: [["indesirable", "Calque."], ["indeseabel", "Indeseable."]], tip: "Un indeseable = un sale type. Efectos indeseables = effets indésirables. Correo no deseado = spam." },
  "nevera": { reg: "gen", alt: [["frigorífico", "Espagne, neutre"], ["frigo", "Espagne, familier"], ["refrigerador", "Mexique et Amérique latine"], ["heladera", "Argentine, Uruguay"], ["refri", "Mexique, familier"]], err: [["nebera", "Avec v."], ["nieve", "Nieve = neige."]], tip: "Espagne, Colombie, Venezuela, Caraïbes : nevera. Mexique : refrigerador, refri. Argentine : heladera. Vient de nieve." },
  "rostro": { reg: "gen", alt: [["cara", "le mot courant"], ["semblante", "littéraire"], ["jeta", "familier, vulgaire"], ["faz", "poétique"]], err: [["rostre", "Rostro."], ["visaje", "Calque."]], tip: "Soutenu ou journalistique. Espagne, familier : tener rostro, tener mucha cara = avoir du culot. ¡Qué rostro tienes!" },
  "casado": { reg: "gen", alt: [["comprometido", "= fiancé"], ["emparejado", "= en couple"], ["esposado", "attention : = menotté"]], err: [["casado a", "Casado CON."], ["cazado", "Cazado = chassé."]], tip: "Estar casado con (ser casado s'entend en Amérique latine). Recién casados = jeunes mariés. Casarse con = se marier avec. Costa Rica : un casado = plat complet typique." },
  "huir": { reg: "gen", alt: [["escapar"], ["fugarse", "= s'évader"], ["largarse", "familier"], ["darse a la fuga", "style policier"]], err: [["huyir", "Infinitif : huir."], ["huo", "Avec y : huyo."]], tip: "Huyo, huyes, huimos ; huyó, huyeron ; huyendo. Huir de = fuir quelque chose. La huida = la fuite." },
  "bajarse de": { reg: "gen", alt: [["descender de", "soutenu"], ["apearse de", "Espagne, soutenu"], ["salir de"]], err: [["bajarse a", "Bajarse DE."], ["bajar del", "Sans se, moins idiomatique pour un véhicule."]], tip: "Me bajo en la próxima = je descends à la prochaine. Bajarse del coche. Contraire : subirse a. Bajarse del carro = se retirer d'un projet." },
  "alcanzar": { reg: "gen", alt: [["lograr", "= atteindre un but"], ["llegar a"], ["pillar", "Espagne : rattraper"], ["bastar", "= suffire"], ["pasar", "= passer un objet"]], err: [["alcansar", "Avec z."], ["atrapar", "Atrapar = attraper, capturer."]], tip: "Alcanzar la cima. No alcanzo = je n'arrive pas à l'attraper. Alcánzame la sal (Amérique latine). No me alcanza el dinero = je n'ai pas assez. Prétérit : alcancé." },
  "marcador": { reg: "gen", alt: [["resultado", "= score"], ["tanteo", "Espagne"], ["tablero", "Amérique latine"], ["rotulador", "Espagne : feutre"], ["plumón", "Mexique, Chili : feutre"]], err: [["marcator", "Marcador."], ["marquador", "Avec c."]], tip: "Abrir el marcador = ouvrir le score. Ir por delante en el marcador. Aussi : marque-page, signet. Amérique latine : marcador = feutre." },
  "mientras": { reg: "gen", alt: [["durante", "+ nom"], ["en tanto que", "soutenu"], ["siempre que", "= tant que, à condition que"], ["mientras tanto", "= pendant ce temps"]], err: [["mientras que", "Mientras que = tandis que (opposition)."], ["durante que", "Mientras."]], tip: "Mientras + indicatif = pendant que. Mientras + subjonctif = tant que : mientras viva. Mientras tanto = en attendant. Mientras más… más (Amérique latine)." },
  "creerse": { reg: "gen", alt: [["presumir", "= frimer"], ["dárselas de", "= se la jouer"], ["tragarse", "= gober"], ["ir de", "Espagne : va de listo"]], err: [["creerse de", "Se cree el mejor : sans préposition."], ["crerse", "Deux e."]], tip: "¿Quién te crees que eres? = pour qui tu te prends ? Se lo tiene muy creído = il s'y croit. No me lo creo = je n'y crois pas. Un creído = un prétentieux." },
  "pensión alimenticia": { reg: "gen", alt: [["pensión de alimentos"], ["manutención", "pour les enfants"], ["pensión compensatoria", "Espagne : pour l'ex-conjoint"], ["cuota alimentaria", "Argentine, Colombie"]], err: [["pension alimenticia", "Avec accent : pensión."], ["pensión alimentaria", "Se dit dans certains pays ; alimenticia est le plus répandu."]], tip: "Pasar la pensión = verser la pension. Espagne : pensión de alimentos (enfants), pensión compensatoria (ex-conjoint)." },
  "manutención": { reg: "gen", alt: [["sustento", "= subsistance"], ["pensión alimenticia"], ["mantenimiento", "= entretien, maintenance"]], err: [["manutencion", "Avec accent."], ["manutensión", "Avec c."]], tip: "Gastos de manutención = frais de subsistance. Pour une machine : mantenimiento. Faux ami : la manutention = manipulación de cargas." },
  "estar encima de": { reg: "gen", alt: [["agobiar", "= étouffer, stresser"], ["controlar"], ["vigilar de cerca"], ["marcar de cerca", "sport"], ["no dejar en paz"]], err: [["ser encima de", "Avec ESTAR."], ["estar en cima de", "Encima, en un mot."]], tip: "Mi jefe está siempre encima de mí = mon chef est toujours sur mon dos. Encima = en plus : y encima llueve. Quitarse a alguien de encima = se débarrasser de quelqu'un." },
  "apenas": { reg: "gen", alt: [["casi no"], ["solo", "= seulement"], ["en cuanto", "= dès que"], ["nada más", "nada más llegar = à peine arrivé"]], err: [["a penas", "En un mot (a duras penas = à grand-peine)."], ["apeinas", "Apenas."]], tip: "Apenas come = il mange à peine. Apenas llegó, se fue = à peine arrivé. Amérique latine : apenas = dès que, ou seulement : apenas son las dos." },
  "pasar de": { reg: "es", alt: [["ignorar"], ["no hacer caso a"], ["desentenderse de"], ["sudar de", "Espagne, vulgaire"], ["no dar bola", "Argentine"]], err: [["pasar a", "Pasar DE."], ["pasar sobre", "DE."]], tip: "Espagne, familier. Paso de ti = je me fous de toi. Paso = sans moi. Un pasota = un je-m'en-foutiste. Pasar de + nombre = dépasser." },
  "apañárselas": { reg: "es", alt: [["arreglárselas", "universel"], ["ingeniárselas", "= trouver une astuce"], ["buscarse la vida", "Espagne"], ["rebuscárselas", "Argentine, Colombie"], ["componérselas"]], err: [["apanárselas", "Avec ñ."], ["apañárselos", "Toujours las : apañárselas."]], tip: "Espagne. Me las apaño = je me débrouille. Ya te las apañarás. Un apaño = une solution de fortune. Universel : arreglárselas." },
  "vivir a lo rústico": { reg: "gen", alt: [["vivir sin comodidades"], ["vivir a lo bruto"], ["vivir de forma austera"], ["pasar penurias", "= vivre dans le besoin"]], err: [["vivir al rústico", "A lo rústico."]], tip: "Peu figé. A lo + adjectif = à la manière : a lo grande (en grand), a lo loco (n'importe comment), a lo bestia (comme une brute)." },
  "colchón": { reg: "gen", alt: [["colchoneta", "= petit matelas"], ["cama", "par extension"], ["somier", "= sommier"]], err: [["colchon", "Avec accent."], ["matelas", "Mot français."]], tip: "Pluriel : colchones. Au figuré : un colchón financiero = un matelas de sécurité. Los colchoneros = surnom de l'Atlético de Madrid." },
  "colchoneta": { reg: "gen", alt: [["esterilla", "Espagne : tapis de sol, de yoga"], ["tapete", "Amérique latine"], ["tatami"], ["colchón hinchable", "= matelas gonflable"]], err: [["colchonetta", "Un seul t."], ["colchonita", "Colchoneta."]], tip: "Colchoneta de gimnasia, de playa. Espagne : esterilla pour le yoga et le camping." },
  "colegiado": { reg: "gen", alt: [["titulado", "= diplômé"], ["habilitado"], ["matriculado", "Argentine"], ["árbitro", "= arbitre"]], err: [["collegiado", "Un seul l."], ["colegial", "Colegial = écolier, collégien."]], tip: "Inscrit à un colegio profesional (ordre professionnel) : abogado colegiado. En Espagne, les commentateurs disent el colegiado pour l'arbitre." },
  "fletar": { reg: "gen", alt: [["alquilar", "= louer"], ["contratar"], ["rentar", "Mexique"]], err: [["affretar", "Calque."], ["flotar", "Flotar = flotter."]], tip: "Fletar un avión, un barco, un autobús. Un vuelo chárter. Argentine, familier : fletar a alguien = le virer." },
  "avión de carga": { reg: "gen", alt: [["avión carguero"], ["carguero"], ["avión de mercancías", "Espagne"]], err: [["avion de carga", "Avec accent : avión."], ["avión cargo", "Avión de carga."]], tip: "Pluriel : aviones de carga. Un buque de carga = un cargo." },
  "barriga": { reg: "gen", alt: [["tripa", "Espagne"], ["panza", "universel, plus familier"], ["vientre", "neutre, soutenu"], ["guata", "Chili"], ["estómago"]], err: [["bariga", "Deux r."], ["barigua", "Barriga."]], tip: "Me duele la barriga. Echar barriga = prendre du ventre. Espagne : tripa. Rascarse la barriga = se tourner les pouces." },
  "panza": { reg: "gen", alt: [["barriga"], ["tripa", "Espagne"], ["timba", "Mexique, familier"], ["guata", "Chili"]], err: [["pansa", "Avec z."], ["pança", "Panza."]], tip: "Plus familier que barriga, très courant en Argentine et au Mexique. Sancho Panza. Un panzazo = un plat (plongeon). De panza = à plat ventre." },
  "bodega": { reg: "gen", alt: [["almacén", "= entrepôt"], ["depósito"], ["sótano", "= sous-sol"], ["cava", "= cave à vin"], ["galpón", "Amérique du Sud : hangar"]], err: [["bodéga", "Sans accent."], ["botega", "Avec d."]], tip: "Espagne : cave à vin, domaine viticole. Amérique latine : entrepôt, épicerie de quartier (Caraïbes, Pérou). La bodega del avión = la soute." },
  "llenar a tope": { reg: "es", alt: [["llenar hasta arriba"], ["llenar al máximo", "universel"], ["llenar hasta el tope", "Amérique latine"], ["abarrotar", "= bonder"]], err: [["llenar al tope", "En Espagne : a tope."], ["yenar a tope", "Avec ll."]], tip: "A tope (Espagne) = à fond : estoy a tope = je suis débordé, ou à fond. Música a tope. El bar estaba a tope." },
  "arancel": { reg: "gen", alt: [["derecho de aduana"], ["tarifa aduanera"], ["impuesto de importación"], ["gravamen", "= taxe, charge"]], err: [["aranzel", "Avec c."], ["tarifa", "Tarifa = tarif, prix."]], tip: "Imponer aranceles a = imposer des droits de douane sur. Pluriel : aranceles. Adjectif : arancelario. Argentine : arancel = aussi frais d'inscription." },
  "flete": { reg: "gen", alt: [["transporte"], ["porte", "Espagne : frais de port"], ["envío", "= envoi, livraison"], ["acarreo"]], err: [["fleto", "Flete."], ["fret", "Flete."]], tip: "El costo del flete. Amérique latine : un flete = un service de camionnette de déménagement. Verbe : fletar." },
  "mercancía": { reg: "gen", alt: [["mercadería", "Amérique du Sud"], ["género", "Espagne : la marchandise d'un commerce"], ["productos"], ["bienes", "= biens"]], err: [["mercancia", "Avec accent."], ["marchandisa", "Calque."]], tip: "Tren de mercancías = train de marchandises (Espagne). Amérique du Sud : mercadería. Mercado, mercader : même famille." },
  "carga": { reg: "gen", alt: [["cargamento", "= cargaison"], ["peso", "= poids"], ["responsabilidad"], ["recarga", "= recharge"], ["lastre", "= fardeau"]], err: [["cargo", "El cargo = le poste, la fonction. La carga = la charge."], ["charga", "Avec c."]], tip: "Zona de carga y descarga. Una carga de trabajo. Ser una carga para alguien. Volver a la carga = revenir à la charge. La carga de la batería." },
});

// Fiches des mots du bundle du 12/11 (cours « Perso »)
Object.assign(CRS_FB.es, {
  "gastar": { reg: "gen", alt: [["derrochar", "= gaspiller, jeter l'argent par les fenêtres"], ["malgastar", "= mal dépenser"], ["desembolsar", "= débourser"], ["consumir", "= consommer"]], err: [["gastar en dinero", "Gastar dinero EN algo."], ["dispensar", "Dispensar = dispenser, excuser. Dépenser = gastar."]], tip: "Gastar dinero en ropa. Aussi : user (gastar los zapatos) et consommer (este coche gasta mucho). Los gastos = les dépenses. En Espagne : gastar una broma = faire une blague." },
  "alquileres": { reg: "gen", alt: [["renta", "Mexique : le loyer"], ["arriendo", "Chili, Colombie"], ["arrendamiento", "terme juridique"], ["mensualidad", "= la mensualité"]], err: [["alquilers", "Pluriel en -es : alquileres."], ["los alquilos", "El alquiler, los alquileres."]], tip: "Singulier : el alquiler. Alquilar = louer ; un piso de alquiler = un appartement en location. En Espagne on dit alquiler ; au Mexique renta, au Chili et en Colombie arriendo." },
  "palillo": { reg: "gen", alt: [["mondadientes", "= cure-dent, compris partout"], ["escarbadientes", "Argentine, Uruguay"], ["palillos chinos", "= les baguettes pour manger"], ["baqueta", "= baguette de batterie"]], err: [["palilo", "Double l : palillo."], ["paleta", "Paleta = palette, ou sucette glacée au Mexique."]], tip: "Diminutif de palo (bâton). En Espagne, palillo = cure-dent ; los palillos = les baguettes (chinoises ou de tambour). Estar como un palillo = être maigre comme un clou." },
  "estancarse": { reg: "gen", alt: [["atascarse", "= se coincer, s'enliser"], ["paralizarse", "= se paralyser"], ["quedarse parado", "= rester à l'arrêt"], ["no avanzar", "= ne pas avancer"]], err: [["estanquarse", "Avec c : estancarse. Mais au passé simple : me estanqué."], ["estancar la sed", "Étancher sa soif = saciar la sed."]], tip: "Agua estancada = eau stagnante. Las negociaciones se han estancado. Un estanque = un bassin. En Espagne, un estanco = un bureau de tabac." },
  "mudarse": { reg: "gen", alt: [["trasladarse", "= se déplacer, être muté"], ["cambiarse de casa", "courant, surtout au Mexique"], ["irse a vivir a", "= aller vivre à"], ["instalarse", "= s'installer"]], err: [["mudar", "Sans se, mudar = changer, muer. Déménager = mudarSE."], ["mudarse en Madrid", "Mudarse A Madrid."]], tip: "Mudarse de casa, mudarse a otra ciudad. La mudanza = le déménagement. Mudar de piel = muer. Mudo = muet, sans rapport." },
  "tenerlo grabado en la mente": { reg: "gen", alt: [["tenerlo grabado a fuego", "= gravé au fer rouge, plus fort"], ["no poder quitárselo de la cabeza", "= ne pas pouvoir se l'enlever de la tête"], ["quedarse grabado", "se me quedó grabado = ça m'a marqué"], ["tenerlo presente", "= l'avoir à l'esprit"]], err: [["gravado", "Avec b : grabado. Gravar = taxer."], ["la tengo grabado", "L'accord suit le complément : la tengo grabadA, lo tengo grabadO."]], tip: "Grabar = graver, et aussi enregistrer (grabar un vídeo). Lo tengo grabado en la mente = c'est gravé dans ma mémoire. Variante : en la memoria. Le participe s'accorde : esa melodía la tengo grabada." },
});

// Fiches des mots du journal qui n'étaient pas dans le paquet
Object.assign(CRS_FB.es, {
  "dar ganas / miedo / pena": { reg: "gen", alt: [["tener ganas de", "= avoir envie de (c'est moi le sujet)"], ["apetecer", "Espagne : me apetece = ça me dit"], ["asustar", "= faire peur"], ["dar lástima", "= faire pitié"]], err: [["yo doy ganas de salir", "Se construit comme gustar : ME DAN ganas de salir."], ["me da pena = j'ai honte ?", "En Espagne : ça me fait de la peine. Au Mexique et en Colombie : j'ai honte."]], tip: "Dar + nom se construit comme gustar : me da miedo, me dan ganas de llorar, me da pena verlo así. Même schéma : dar vergüenza, dar asco, dar igual, dar rabia." },
  "aguantar": { reg: "gen", alt: [["soportar", "= supporter, plus neutre"], ["tolerar", "= tolérer"], ["resistir", "= résister"], ["bancar", "Argentine, Uruguay : no te banco"]], err: [["no lo soporto ≠ no lo aguanto ?", "Les deux se disent. Aguantar est plus oral."], ["aguantar = attendre", "Aguanta un momento = tiens bon, patiente un instant."]], tip: "No aguanto más = je n'en peux plus. No lo aguanto = je ne le supporte pas. Aguantar la respiración = retenir son souffle. Aguantarse = prendre sur soi : ¡te aguantas! = tant pis pour toi." },
  "chapuzas": { reg: "es", alt: [["chapuza", "= le travail bâclé lui-même"], ["chambón", "Amérique latine : maladroit, bâcleur"], ["manitas", "Espagne : le contraire, un bon bricoleur"], ["trabajo mal hecho"]], err: [["un chapuza = un travail bâclé", "Una chapuza = le travail bâclé. Un chapuzas = celui qui bâcle."], ["chapuzón", "Un chapuzón = un plongeon, une baignade rapide."]], tip: "Espagne. Una chapuza = du bricolage, du travail ni fait ni à faire. Ser un chapuzas = bâcler tout ce qu'on touche. Hacer chapuzas = faire des petits travaux, parfois au noir." },
  "empapado": { reg: "gen", alt: [["mojado", "= mouillé, moins fort"], ["calado", "Espagne : calado hasta los huesos"], ["chorreando", "= dégoulinant"], ["hecho una sopa", "familier : trempé comme une soupe"]], err: [["empapelado", "Empapelado = tapissé de papier peint."], ["estoy empapada (homme)", "S'accorde : empapado, empapada."]], tip: "Empapar = tremper. Llegué empapado = je suis arrivé trempé. Empapado en sudor = trempé de sueur. Empaparse de algo = s'imprégner de quelque chose (une culture, un sujet)." },
  "encajar": { reg: "gen", alt: [["caber", "= rentrer, tenir dans un espace"], ["cuadrar", "= coller, concorder"], ["pegar", "Espagne, familier : no pega = ça ne va pas ensemble"], ["asumir", "= encaisser (une nouvelle)"]], err: [["encajar = encaisser de l'argent", "Encaisser de l'argent = cobrar."], ["encargar", "Encargar = commander, charger quelqu'un de."]], tip: "Trois sens. S'emboîter : las piezas encajan. S'intégrer : no encajo en este grupo. Encaisser : encajar un golpe, un gol, una crítica. Algo no encaja = il y a quelque chose qui cloche." },
  "estar al tanto": { reg: "gen", alt: [["estar al corriente", "même sens"], ["estar enterado", "= être au courant"], ["estar al día", "= être à jour"], ["estar pendiente", "= être attentif à, guetter"]], err: [["estar al tanto que", "Estar al tanto DE algo."], ["ser al tanto", "Avec estar."]], tip: "Estoy al tanto de todo = je suis au courant de tout. Mantener a alguien al tanto = tenir quelqu'un au courant. Ponerse al tanto = se mettre au courant." },
  "jalar": { reg: "latam", alt: [["tirar de", "Espagne : tirer"], ["halar", "Caraïbes, Colombie, Venezuela : même verbe, autre graphie"], ["zampar", "Espagne, familier : s'empiffrer"], ["papear", "Espagne, argot : manger"]], err: [["jalar la puerta (en Espagne)", "En Espagne : tirar de la puerta."], ["jalar = toujours tirer", "En Espagne, jalar est de l'argot pour manger."]], tip: "Amérique latine : tirer (jala la puerta). Sur les portes : jale / empuje. Au Mexique : jalar = marcher, fonctionner (no jala) et ¿jalas? = tu viens ? En Espagne, argot : manger. Au Pérou : jalar un examen = le rater." },
  "madrugar": { reg: "gen", alt: [["levantarse temprano", "neutre"], ["levantarse al alba", "= se lever à l'aube"], ["trasnochar", "le contraire : veiller tard"], ["pegarse un madrugón", "Espagne, familier : se lever aux aurores"]], err: [["madrugar temprano", "Pléonasme : madrugar suffit."], ["madurar", "Madurar = mûrir."]], tip: "De madrugada (la fin de nuit). Mañana me toca madrugar. Proverbes : a quien madruga, Dios le ayuda ; no por mucho madrugar amanece más temprano. Un madrugador = un lève-tôt." },
  "malgastar": { reg: "gen", alt: [["derrochar", "= dilapider, plus fort"], ["despilfarrar", "= gaspiller sans compter"], ["desperdiciar", "= gâcher (nourriture, occasion)"], ["tirar el dinero", "familier : jeter l'argent par les fenêtres"]], err: [["malgastar comida", "Pour la nourriture ou une occasion : desperdiciar."], ["mal gastar", "En un seul mot : malgastar."]], tip: "Mal + gastar. Malgastar el dinero, el tiempo, la energía. No malgastes tu tiempo con eso. Pour ce qu'on gâche ou qu'on laisse perdre : desperdiciar." },
  "maña": { reg: "gen", alt: [["habilidad", "= habileté, neutre"], ["destreza", "= adresse"], ["truco", "= astuce, truc"], ["mañas", "Amérique latine, au pluriel : manies, mauvaises habitudes"]], err: [["mana", "Avec ñ : maña."], ["mañana", "Mañana = demain, matin."]], tip: "Tener maña para algo = être doué de ses mains. Darse maña = se débrouiller. Más vale maña que fuerza = mieux vaut ruse que force. Un mañoso = un adroit (Espagne) ou un capricieux (Amérique latine). En Espagne, maño = Aragonais." },
  "tirón": { reg: "gen", alt: [["jalón", "Amérique latine : coup sec"], ["estirón", "= poussée de croissance"], ["calambre", "= crampe"], ["robo por tirón", "Espagne : vol à l'arraché"]], err: [["tiron", "Avec accent : tirón. Pluriel sans accent : tirones."], ["de un tiro", "De un tiro = d'un coup de feu. D'une traite = de un tirón."]], tip: "De tirar. Dar un tirón = tirer d'un coup sec. De un tirón = d'une traite (me leí el libro de un tirón). Un tirón muscular = un claquage. En Espagne : el tirón = le vol à l'arraché, et tener tirón = avoir du succès." },
  "tutear": { reg: "gen", alt: [["tratar de tú", "même sens"], ["hablar de tú", "courant"], ["tratar de usted", "le contraire : vouvoyer"], ["vosear", "Argentine, Uruguay : dire vos"]], err: [["tutoyar", "Tutear."], ["tutear a usted", "On tutoie quelqu'un : tutear A alguien. ¿Nos tuteamos?"]], tip: "¿Te puedo tutear? / ¿Nos tuteamos? = on se tutoie ? En Espagne on tutoie très vite. En Amérique latine, usted reste plus fréquent ; en Colombie on l'emploie même entre proches. El tuteo = le tutoiement." },
  "decidir": { reg: "gen", alt: [["decidirse a", "= se décider à"], ["decidirse por", "= opter pour"], ["resolver", "= résoudre, trancher"], ["optar por", "= opter pour"], ["determinar", "formel"]], err: [["decidir de hacer", "Sans préposition : decidir hacer algo. Mais decidirse A hacer."], ["decidó", "Régulier en -ir : decidió."]], tip: "He decidido quedarme. Decidirse a + infinitif (me decidí a llamar), decidirse por + nom (me decidí por el azul). Una decisión : tomar una decisión, jamais hacer. Estar decidido a = être résolu à." },
  "alcanzar en el marcador": { reg: "gen", alt: [["empatar", "= égaliser"], ["igualar", "= égaliser"], ["remontar", "= remonter au score, renverser le match"], ["dar la vuelta al marcador", "= renverser le score"]], err: [["alcanzar al marcador", "Alcanzar a alguien EN el marcador."], ["el marcador = le marqueur", "El marcador = le tableau d'affichage, le score. Le buteur = el goleador."]], tip: "Alcanzar = rattraper, atteindre. El marcador = le score. Abrir el marcador = ouvrir le score. Ir por delante / por detrás en el marcador = mener / être mené." },
  "mientras ganemos": { reg: "gen", alt: [["siempre que ganemos", "= à condition qu'on gagne"], ["con tal de que ganemos", "= pourvu qu'on gagne"], ["mientras ganamos", "indicatif : pendant qu'on gagne (simultanéité)"]], err: [["mientras ganamos = tant qu'on gagne", "La condition demande le subjonctif : mientras ganemos."], ["mientras que ganemos", "Mientras que marque l'opposition (tandis que), pas la condition."]], tip: "Mientras + subjonctif = tant que, du moment que (condition tournée vers l'avenir). Mientras + indicatif = pendant que. Mientras tanto = pendant ce temps. Ganemos : subjonctif présent de ganar, nosotros." },
  "apenas mirar": { reg: "gen", alt: [["casi no mirar", "= presque pas"], ["mirar de reojo", "= regarder du coin de l'œil"], ["echar un vistazo", "= jeter un coup d'œil"], ["ni siquiera mirar", "= ne même pas regarder"]], err: [["a penas", "En un seul mot : apenas."], ["no apenas miró", "Devant le verbe, pas de no : apenas me miró. Après le verbe : no me miró apenas."]], tip: "Apenas = à peine. Apenas me miró = il m'a à peine regardé. Apenas + verbe = dès que, surtout en Amérique latine : apenas llegue, te llamo. Apenas si = c'est tout juste si." },
});

